// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * @title AuditLog
 * @dev Immutable on-chain audit trail for sensitive barangay health center events.
 *      Events are append-only; nothing can be deleted or altered after logging.
 *
 *      Use cases:
 *      - QR scan access events (who scanned whose record, outcome)
 *      - Resident referrals between barangays
 *      - Critical health record mutations (create, update)
 *      - Login anomalies / security incidents
 */
contract AuditLog {
    // ── Event types (mirrors QrScanAction and other app events) ──────────────

    uint8 public constant EVT_QR_SCAN_GRANTED   = 1;
    uint8 public constant EVT_QR_SCAN_DENIED    = 2;
    uint8 public constant EVT_RECORD_CREATED    = 3;
    uint8 public constant EVT_RECORD_UPDATED    = 4;
    uint8 public constant EVT_REFERRAL_CREATED  = 5;
    uint8 public constant EVT_REFERRAL_ACCEPTED = 6;
    uint8 public constant EVT_REFERRAL_REJECTED = 7;
    uint8 public constant EVT_APPT_BOOKED       = 8;
    uint8 public constant EVT_APPT_COMPLETED    = 9;

    // ── Structures ───────────────────────────────────────────────────────────

    struct AuditEntry {
        uint256 id;
        uint8   eventType;
        string  actorId;      // user/staff UUID (off-chain)
        string  targetId;     // resident/record UUID (off-chain)
        string  barangayId;   // which barangay
        bytes32 dataHash;     // optional: hash of the related data payload
        string  metadata;     // small JSON string (role, IP hash, etc.)
        uint256 timestamp;
    }

    // ── Storage ──────────────────────────────────────────────────────────────

    AuditEntry[] private _log;
    uint256 private _counter;

    address public owner;

    // ── Events ───────────────────────────────────────────────────────────────

    event Logged(
        uint256 indexed id,
        uint8   indexed eventType,
        string  actorId,
        string  targetId,
        string  barangayId,
        bytes32 dataHash,
        uint256 timestamp
    );

    // ── Modifiers ────────────────────────────────────────────────────────────

    modifier onlyOwner() {
        require(msg.sender == owner, "Not authorised");
        _;
    }

    constructor() {
        owner = msg.sender;
    }

    // ── Write ─────────────────────────────────────────────────────────────────

    /**
     * @notice Append an audit event to the immutable log.
     * @param eventType  One of the EVT_* constants above.
     * @param actorId    UUID of the staff/user performing the action.
     * @param targetId   UUID of the resident or resource being acted on.
     * @param barangayId UUID of the barangay context.
     * @param dataHash   Optional keccak256 hash of the related payload (pass bytes32(0) to skip).
     * @param metadata   Small JSON string e.g. '{"role":"NURSE","ipHash":"0xabc"}'. Max 512 chars.
     * @return id        The sequential audit log entry ID.
     */
    function logEvent(
        uint8 eventType,
        string calldata actorId,
        string calldata targetId,
        string calldata barangayId,
        bytes32 dataHash,
        string calldata metadata
    ) external onlyOwner returns (uint256 id) {
        require(eventType >= 1 && eventType <= 9, "Unknown event type");
        require(bytes(metadata).length <= 512, "Metadata too long");

        id = _counter++;

        _log.push(AuditEntry({
            id:         id,
            eventType:  eventType,
            actorId:    actorId,
            targetId:   targetId,
            barangayId: barangayId,
            dataHash:   dataHash,
            metadata:   metadata,
            timestamp:  block.timestamp
        }));

        emit Logged(id, eventType, actorId, targetId, barangayId, dataHash, block.timestamp);
    }

    // ── Read ──────────────────────────────────────────────────────────────────

    /**
     * @notice Total number of log entries.
     */
    function totalEntries() external view returns (uint256) {
        return _log.length;
    }

    /**
     * @notice Retrieve a single audit entry by ID.
     */
    function getEntry(uint256 id)
        external
        view
        returns (
            uint8   eventType,
            string memory actorId,
            string memory targetId,
            string memory barangayId,
            bytes32 dataHash,
            string memory metadata,
            uint256 timestamp
        )
    {
        require(id < _log.length, "Entry does not exist");
        AuditEntry storage e = _log[id];
        return (e.eventType, e.actorId, e.targetId, e.barangayId, e.dataHash, e.metadata, e.timestamp);
    }

    /**
     * @notice Retrieve a page of entries (newest-first friendly via offset+limit).
     * @param offset Starting index (0-based).
     * @param limit  Max entries to return (capped at 100).
     */
    function getEntries(uint256 offset, uint256 limit)
        external
        view
        returns (AuditEntry[] memory entries)
    {
        uint256 total = _log.length;
        if (offset >= total) return new AuditEntry[](0);

        uint256 cap = limit > 100 ? 100 : limit;
        uint256 end = offset + cap;
        if (end > total) end = total;

        entries = new AuditEntry[](end - offset);
        for (uint256 i = offset; i < end; i++) {
            entries[i - offset] = _log[i];
        }
    }
}

contracts/HealthRecordRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * @title HealthRecordRegistry
 * @dev Stores SHA-256 hashes of resident health records on-chain.
 *      Raw health data is NEVER stored here — only hashes for integrity verification.
 *      Compliant with the Philippine Data Privacy Act (RA 10173).
 */
contract HealthRecordRegistry {
    // ── Events ──────────────────────────────────────────────────────────────

    event RecordAnchored(
        string indexed residentId,
        bytes32 recordHash,
        string  recordType,
        uint256 timestamp,
        address anchoredBy
    );

    event RecordRevoked(
        string indexed residentId,
        bytes32 recordHash,
        uint256 timestamp,
        address revokedBy
    );

    // ── Data structures ──────────────────────────────────────────────────────

    struct RecordEntry {
        bytes32 hash;       // SHA-256 hash of the off-chain health record JSON
        string  recordType; // "medical_history" | "family_history" | "personal_social" | "resident_profile"
        uint256 timestamp;  // block.timestamp when anchored
        address anchoredBy; // address of the system wallet that submitted the tx
        bool    revoked;    // true if this record version was superseded / revoked
    }

    // residentId (off-chain UUID) → ordered list of record versions
    mapping(string => RecordEntry[]) private _records;

    // Quick lookup: hash → bool (exists on chain)
    mapping(bytes32 => bool) private _hashExists;

    address public owner;

    // ── Modifiers ────────────────────────────────────────────────────────────

    modifier onlyOwner() {
        require(msg.sender == owner, "Not authorised");
        _;
    }

    constructor() {
        owner = msg.sender;
    }

    // ── Write ─────────────────────────────────────────────────────────────────

    /**
     * @notice Anchor a new hash for a resident's health record.
     * @param residentId  The off-chain UUID of the resident.
     * @param recordHash  keccak256 or SHA-256 (as bytes32) of the serialised record JSON.
     * @param recordType  One of: "medical_history", "family_history", "personal_social", "resident_profile".
     */
    function anchorRecord(
        string calldata residentId,
        bytes32 recordHash,
        string calldata recordType
    ) external onlyOwner {
        require(recordHash != bytes32(0), "Empty hash");
        require(!_hashExists[recordHash], "Hash already anchored");

        _records[residentId].push(
            RecordEntry({
                hash:       recordHash,
                recordType: recordType,
                timestamp:  block.timestamp,
                anchoredBy: msg.sender,
                revoked:    false
            })
        );

        _hashExists[recordHash] = true;

        emit RecordAnchored(residentId, recordHash, recordType, block.timestamp, msg.sender);
    }

    /**
     * @notice Revoke a record version (e.g. when data is corrected under DPA request).
     * @param residentId The resident whose record version is being revoked.
     * @param index      Index of the version in the resident's record history.
     */
    function revokeRecord(string calldata residentId, uint256 index) external onlyOwner {
        require(index < _records[residentId].length, "Index out of range");
        RecordEntry storage entry = _records[residentId][index];
        require(!entry.revoked, "Already revoked");

        entry.revoked = true;
        emit RecordRevoked(residentId, entry.hash, block.timestamp, msg.sender);
    }

    // ── Read ──────────────────────────────────────────────────────────────────

    /**
     * @notice Verify whether a given hash exists and is not revoked.
     * @return exists   true if the hash was ever anchored.
     * @return revoked  true if the hash was subsequently revoked.
     */
    function verifyHash(bytes32 recordHash) external view returns (bool exists, bool revoked) {
        exists = _hashExists[recordHash];
        if (!exists) return (false, false);

        // Scan to find revocation status (hashes are globally unique so there's only one)
        // In practice this is called rarely and gas is not a concern server-side.
        revoked = false;
        // We cannot return revocation status purely from _hashExists;
        // caller should use getRecordHistory and inspect the matching entry.
        return (exists, false);
    }

    /**
     * @notice Get the number of record versions for a resident.
     */
    function getRecordCount(string calldata residentId) external view returns (uint256) {
        return _records[residentId].length;
    }

    /**
     * @notice Get a specific version of a resident's record entry.
     */
    function getRecord(string calldata residentId, uint256 index)
        external
        view
        returns (
            bytes32 hash,
            string memory recordType,
            uint256 timestamp,
            address anchoredBy,
            bool revoked
        )
    {
        require(index < _records[residentId].length, "Index out of range");
        RecordEntry storage e = _records[residentId][index];
        return (e.hash, e.recordType, e.timestamp, e.anchoredBy, e.revoked);
    }

    /**
     * @notice Get the latest (most recent) record hash for a resident, for a given type.
     *         Returns (bytes32(0), false) if no active record exists.
     */
    function getLatestRecord(string calldata residentId, string calldata recordType)
        external
        view
        returns (bytes32 latestHash, uint256 latestTimestamp)
    {
        RecordEntry[] storage entries = _records[residentId];
        for (uint256 i = entries.length; i > 0; i--) {
            RecordEntry storage e = entries[i - 1];
            if (!e.revoked && keccak256(bytes(e.recordType)) == keccak256(bytes(recordType))) {
                return (e.hash, e.timestamp);
            }
        }
        return (bytes32(0), 0);
    }
}

